$ErrorActionPreference='Stop'
$root=(Resolve-Path (Join-Path $PSScriptRoot '../..')).Path
$files=@('dataset/yelp_business_1000.csv','dataset/yelp_reviews_1000.csv','data/cleaned/vendor_profiles_missingness_checked.csv','hybrid_simulation_v1/real_vendor_profiles.csv','hybrid_simulation_v1/synthetic_service_options.csv','hybrid_simulation_v1/synthetic_event_requirements.csv','hybrid_simulation_v1/synthetic_availability.csv','hybrid_simulation_v1/synthetic_collaboration_scenarios.csv','hybrid_simulation_v1/hybrid_vendor_service_dataset.csv','hybrid_simulation_v1/field_provenance.csv','vendor_compatibility_matrix.csv','vendor_risk_dataset.csv','vendor_availability.csv','vendor_service_details.csv','event_requirements.csv','venue_constraints.csv','models/vendor_risk_random_forest.pkl','vendor_risk_model.pkl','research_evaluation/evaluation_results.csv','research_evaluation/baseline_comparison.csv','research_evaluation/ranking_sensitivity.csv','research_evaluation/evaluation_summary.json')
$inventory=foreach($rel in $files){$p=Join-Path $root $rel;if(!(Test-Path -LiteralPath $p)){continue};$f=Get-Item $p;$csv=$f.Extension -eq '.csv';$origin=if($rel -match 'synthetic_|hybrid_vendor|venue_constraints|vendor_availability|vendor_service_details|event_requirements'){'SYNTHETIC_TEST'}elseif($rel -match 'compatibility|risk_dataset|\.pkl|research_evaluation'){'DERIVED'}elseif($rel -match 'yelp_|real_vendor_profiles|vendor_profiles_missingness'){'UNKNOWN'}else{'UNKNOWN'};[pscustomobject]@{path=$rel;rows=if($csv){@(Import-Csv $p).Count}else{$null};bytes=$f.Length;sha256=(Get-FileHash $p -Algorithm SHA256).Hash.ToLowerInvariant();columns=if($csv){Get-Content $p -TotalCount 1}else{''};classification=$origin}}
foreach($row in $inventory){if($row.rows -eq 0){$row.classification='UNKNOWN'}}
$inventory | Export-Csv (Join-Path $PSScriptRoot 'dataset_inventory.csv') -NoTypeInformation -Encoding UTF8

& (Join-Path $PSScriptRoot 'run_fast_quality.ps1')
